local pf={}
local tf=30
local d=100
for i=1,tf do
    pf[i]={}
    for y=1,64 do
        pf[i][y]={}
    end
end
for i=1,tf do
    for y=1,64 do
        for x=1,64 do
            local pxl=fd[i][y][x]
            if pxl then
                local b=Instance.new"Frame"
                b.Size=UDim2.new(0,4,0,4)
                b.Position=UDim2.new(0,(x-1)*4,0,(y-1)*4)
                b.BackgroundColor3=Color3.fromRGB(pxl[1],pxl[2],pxl[3])
                b.BorderSizePixel=0
                b.Parent=f
                b.Visible=(i==1)
                pf[i][y][x]=b
            end
        end
    end
end
local c=1
local t=true
local b=Instance.new"TextButton"
b.Size=UDim2.new(0,60,0,30)
b.Position=UDim2.new(0.5,-80,1,-40)
b.Text="⏸️"
b.Parent=g
local x=Instance.new"TextButton"
