    b.Text=t and"⏸️"or"▶️"
end)
x.MouseButton1Click:Connect(function()
    g:Destroy()
end)
local lt=tick()
r.RenderStepped:Connect(function()
    if t then
        local nt=tick()
        if nt-lt>=d/1000 then
            lt=nt
            for i=1,tf do
                for y=1,64 do
                    for x=1,64 do
                        local px=pf[i] and pf[i][y] and pf[i][y][x]
                        if px then
                            px.Visible=(i==c)
                        end
                    end
                end
            end
            c=c+1
            if c>tf then c=1 end
        end
    end
end)